import unittest

from model_runtime.router import route_task, validate_handoff


class RouterTests(unittest.TestCase):
    def test_discovery_starts_fast(self):
        self.assertEqual(route_task(stage="discovery").role, "fast")

    def test_main_requires_concrete_paths(self):
        self.assertEqual(
            route_task(stage="implementation", target_paths=["nav/settings_benutzer.php"]).role,
            "main",
        )
        self.assertEqual(route_task(stage="implementation").role, "fast")

    def test_repeated_failure_escalates_heavy(self):
        self.assertEqual(route_task(stage="hard-debug", failures=2).role, "heavy")

    def test_explicit_main_without_paths_is_rejected(self):
        with self.assertRaises(ValueError):
            route_task(explicit_role="main")

    def test_handoff_limits_scope(self):
        with self.assertRaises(ValueError):
            validate_handoff(
                "main",
                {"task": "x", "target_paths": [f"f{i}.php" for i in range(13)]},
            )


if __name__ == "__main__":
    unittest.main()
